    10→import kotlinx.coroutines.async
    11→import kotlinx.coroutines.runBlocking
    12→import org.springframework.stereotype.Service
    13→
    14→@Service
    15→class ProxyApplicationService(
    16→    private val brandService: BrandService,
    17→    private val manufacturerService: ManufacturerService,
    18→    private val categoryService: CategoryService,
    19→    private val mallService: MallService,
    20→) {
    21→    fun fetchDependencies(dependencyId: DependencyId): Dependency =
    22→        runBlocking(Dispatchers.IO) {
    23→            val categoriesDeferred =
    24→                async {
    25→                    if (dependencyId.categoryIds.isEmpty()) {
    26→                        emptyMap()
    27→                    } else {
    28→                        categoryService.getCategories(dependencyId.categoryIds).associateBy { it.id }
    29→                    }
    30→                }
    31→            val brandsDeferred =
    32→                async {
    33→                    if (dependencyId.brandIds.isEmpty()) {
    34→                        emptyMap()
    35→                    } else {
    36→                        brandService.getBrands(dependencyId.brandIds).associateBy { it.id }
    37→                    }
    38→                }
    39→            val manufacturersDeferred =
    40→                async {
    41→                    if (dependencyId.manufacturerIds.isEmpty()) {
    42→                        emptyMap()
    43→                    } else {
    44→                        manufacturerService.getManufacturers(dependencyId.manufacturerIds).associateBy { it.id }
    45→                    }
    46→                }
    47→            val mallsDeferred =
    48→                async {
    49→                    if (dependencyId.mallIds.isEmpty()) {
    50→                        emptyMap()
    51→                    } else {
    52→                        mallService.getMalls(dependencyId.mallIds).associateBy { it.mallId }
    53→                    }
    54→                }
    55→
    56→            Dependency(
    57→                categories = categoriesDeferred.await(),
    58→                brands = brandsDeferred.await(),
    59→                manufacturers = manufacturersDeferred.await(),
    60→                malls = mallsDeferred.await(),
    61→            )
    62→        }
    63→}
